CREATE TABLE IF NOT EXISTS migrations (name text PRIMARY KEY, applied_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL, name text NOT NULL, role text NOT NULL DEFAULT 'buyer', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, user_id uuid REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS organizations (id uuid PRIMARY KEY, owner_id uuid REFERENCES users(id), name text NOT NULL, branding jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS members (org_id uuid REFERENCES organizations(id), user_id uuid REFERENCES users(id), permissions jsonb DEFAULT '[]', PRIMARY KEY(org_id,user_id));
CREATE TABLE IF NOT EXISTS plans (id text PRIMARY KEY, name text NOT NULL, price integer NOT NULL CHECK(price>=0), config jsonb NOT NULL, version integer NOT NULL DEFAULT 1, partner_price integer CHECK(partner_price>=0));
CREATE TABLE IF NOT EXISTS orders (id uuid PRIMARY KEY, user_id uuid REFERENCES users(id), org_id uuid REFERENCES organizations(id), channel text NOT NULL CHECK(channel IN ('DIRECT_MANAGED','PARTNER_SELF_SERVICE')), plan_id text REFERENCES plans(id), amount integer NOT NULL, snapshot jsonb NOT NULL, brief jsonb NOT NULL, status text NOT NULL DEFAULT 'awaiting_payment', fulfillment text NOT NULL DEFAULT 'not_started', designer_id uuid REFERENCES users(id), revision_count integer NOT NULL DEFAULT 0, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS events (id uuid PRIMARY KEY, order_id uuid UNIQUE REFERENCES orders(id), org_id uuid REFERENCES organizations(id), customer_id uuid REFERENCES users(id), channel text NOT NULL, slug text UNIQUE NOT NULL, name text NOT NULL, start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Jakarta', status text NOT NULL DEFAULT 'draft', snapshot jsonb NOT NULL, settings jsonb NOT NULL, published jsonb, revision integer NOT NULL DEFAULT 0, reveal_at timestamptz, created_at timestamptz DEFAULT now(), CHECK(end_at>=start_at));
CREATE TABLE IF NOT EXISTS event_staff (event_id uuid REFERENCES events(id), user_id uuid REFERENCES users(id), permissions jsonb NOT NULL, PRIMARY KEY(event_id,user_id));
CREATE TABLE IF NOT EXISTS revisions (id uuid PRIMARY KEY, event_id uuid REFERENCES events(id), version integer NOT NULL, settings jsonb NOT NULL, frames jsonb NOT NULL, created_at timestamptz DEFAULT now(), UNIQUE(event_id,version));
CREATE TABLE IF NOT EXISTS frames (id uuid PRIMARY KEY, event_id uuid REFERENCES events(id), name text NOT NULL, schema jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS requests (id uuid PRIMARY KEY, order_id uuid REFERENCES orders(id), user_id uuid REFERENCES users(id), kind text NOT NULL, message text NOT NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS documents (id uuid PRIMARY KEY, order_id uuid REFERENCES orders(id), kind text NOT NULL, object_key text NOT NULL, mime text NOT NULL, bytes integer NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS guests (id uuid PRIMARY KEY, event_id uuid REFERENCES events(id), identity_hash text NOT NULL, name text NOT NULL, verified boolean NOT NULL DEFAULT false, created_at timestamptz DEFAULT now(), UNIQUE(event_id,identity_hash));
CREATE TABLE IF NOT EXISTS invitations (id uuid PRIMARY KEY, event_id uuid REFERENCES events(id), code_hash text NOT NULL, label text NOT NULL, UNIQUE(event_id,code_hash));
CREATE TABLE IF NOT EXISTS guest_sessions (token_hash text PRIMARY KEY, guest_id uuid REFERENCES guests(id), event_id uuid REFERENCES events(id), snapshot jsonb NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS intents (id uuid PRIMARY KEY, event_id uuid REFERENCES events(id), guest_id uuid REFERENCES guests(id), client_key text NOT NULL, kind text NOT NULL, source text NOT NULL DEFAULT 'guest', max_bytes bigint NOT NULL, mime text NOT NULL, object_key text NOT NULL, state text NOT NULL DEFAULT 'reserved', consent boolean NOT NULL DEFAULT false, privacy text NOT NULL DEFAULT 'private_owner', snapshot jsonb NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz DEFAULT now(), UNIQUE(event_id,guest_id,client_key));
CREATE TABLE IF NOT EXISTS media (id uuid PRIMARY KEY, intent_id uuid UNIQUE REFERENCES intents(id), event_id uuid REFERENCES events(id), guest_id uuid REFERENCES guests(id), kind text NOT NULL, source text NOT NULL DEFAULT 'guest', object_key text, thumbnail_key text, mime text, bytes bigint NOT NULL DEFAULT 0, duration real, text_content text, author text NOT NULL, consent boolean NOT NULL DEFAULT false, moderation text NOT NULL DEFAULT 'pending', processing text NOT NULL DEFAULT 'queued', privacy text NOT NULL DEFAULT 'private_owner', snapshot jsonb NOT NULL DEFAULT '{}', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS display_tokens (token_hash text PRIMARY KEY, event_id uuid REFERENCES events(id), expires_at timestamptz NOT NULL, revoked boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS jobs (id uuid PRIMARY KEY, event_id uuid REFERENCES events(id), user_id uuid REFERENCES users(id), kind text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, error text, result jsonb, run_after timestamptz DEFAULT now(), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS audit (id uuid PRIMARY KEY, actor_id uuid, event_id uuid, action text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS reports (id uuid PRIMARY KEY, media_id uuid REFERENCES media(id), reason text NOT NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limits (key text PRIMARY KEY, hits integer NOT NULL, reset_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS events_org_idx ON events(org_id,created_at);
CREATE INDEX IF NOT EXISTS media_event_idx ON media(event_id,moderation,created_at);
CREATE INDEX IF NOT EXISTS intents_quota_idx ON intents(event_id,guest_id,state,expires_at);
CREATE INDEX IF NOT EXISTS jobs_queue_idx ON jobs(status,run_after);
ALTER TABLE events ENABLE ROW LEVEL SECURITY;
ALTER TABLE orders ENABLE ROW LEVEL SECURITY;
ALTER TABLE media ENABLE ROW LEVEL SECURITY;
ALTER TABLE frames ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION kv_user() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.user_id',true),'')::uuid $$;
CREATE OR REPLACE FUNCTION kv_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM users WHERE id=kv_user() AND role='superadmin') $$;
CREATE OR REPLACE FUNCTION kv_org(org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM organizations WHERE id=org AND owner_id=kv_user()) $$;
CREATE POLICY events_read ON events FOR SELECT USING(customer_id=kv_user() OR kv_org(org_id) OR kv_admin() OR EXISTS(SELECT 1 FROM event_staff WHERE event_id=events.id AND user_id=kv_user()));
CREATE POLICY events_edit ON events FOR UPDATE USING(kv_admin() OR (channel='PARTNER_SELF_SERVICE' AND kv_org(org_id))) WITH CHECK(kv_admin() OR (channel='PARTNER_SELF_SERVICE' AND kv_org(org_id)));
CREATE POLICY orders_read ON orders FOR SELECT USING(user_id=kv_user() OR kv_org(org_id) OR kv_admin());
CREATE POLICY media_read ON media FOR SELECT USING(EXISTS(SELECT 1 FROM events WHERE id=media.event_id));
CREATE POLICY frames_read ON frames FOR SELECT USING(EXISTS(SELECT 1 FROM events WHERE id=frames.event_id));
